// macro que cria um HashMap literal
macro_rules! hashmap {
    ($($k:expr => $v:expr),* $(,)?) => {{
        let mut m = std::collections::HashMap::new();
        $( m.insert($k, $v); )*
        m
    }};
}

fn main() {
    let users = hashmap! {
        "fernando" => 33,
        "ana"      => 28,
    };
    println!("{:?}", users);
}

