use serde::{Serialize, Deserialize};

#[derive(Serialize, Deserialize, Debug)]
struct User {
    id: u64,
    name: String,
    #[serde(default)]
    active: bool,
}

fn main() {
    let u = User { id: 1, name: "Fernando".into(), active: true };
    let json = serde_json::to_string(&u).unwrap();
    println!("{}", json); // {"id":1,"name":"Fernando","active":true}

    let parsed: User = serde_json::from_str(&json).unwrap();
    println!("{:?}", parsed);
}

